    "justification": "The experiment used Affymetrix U133A microarrays to profile RNA from human samples (circulating leukocytes), so it is human microarray expression profiling."
  },
  "q2_target_disease": {
    "answer": "No",
    "evidence": "Title/Description: 'Gene expression patterns in peripheral blood correlate with the extent of coronary artery disease'; RNA was extracted from 110 patients with CAD and 112 controls (CADi metrics).",
    "justification": "The study focuses on coronary artery disease (CAD), not ALS or frontotemporal dementia."
  },
  "q3_human_cns_tissue": {
    "answer": "No",
    "evidence": "Description: 'Gene expression profile in circulating leukocytes'; samples are peripheral blood leukocytes (no organism part / brain region reported).",
    "justification": "Samples are peripheral blood (circulating leukocytes), not human brain/CNS tissue."
  },
  "q4_non_clinical": {
    "answer": "No",
    "evidence": "Description indicates RNA was extracted from patients undergoing coronary angiography (110 patients with CAD and 112 controls); samples are clinical peripheral blood specimens.",
    "justification": "This is an in vivo clinical patient study using blood samples, not patient-derived in vitro cell lines or disease models."
  },
  "q5_case_control_design": {
    "answer": "Yes",
    "evidence": "RNA was extracted from 110 patients with CAD (CADi>23) and from 112 partially matched controls without CAD (CADi=0); 'parallel group design' noted.",
    "justification": "The study compares cases (CAD patients) to controls, i.e., a case/control design."
  },
  "q6_irrelevant_brain_region": {
    "answer": "Yes",
    "evidence": "Samples are circulating leukocytes (peripheral blood); no brain regions or CNS tissues sampled.",
    "justification": "The dataset does not include CNS brain regions and therefore does not sample regions relevant to ALS-FTD neurodegeneration."
  },
  "q7_incompatible_technology": {
    "answer": "No",
    "evidence": "Study type: transcription profiling by array; Affymetrix U133A chips used; Technology: Array assay; Assay by Molecule: RNA assay.",
    "justification": "The technology is microarray-based expression profiling, which is compatible with inclusion requirements (not RNA-seq or proteomics)."
  },
  "q8_inclusion_justification": {
    "justification": "Although the dataset is human and uses microarray expression profiling with a case/control design, it does not pertain to ALS-FTD and does not include CNS tissue—samples are peripheral blood leukocytes from patients with coronary artery disease—so it fails the disease- and tissue-related inclusion criteria."
  },
  "q9_include_dataset": {
    "answer": "No"
  }
}

